<?php
 namespace QQWorld\Framework\TestFramework\Test\Unit\Autoloader; use QQWorld\Framework\TestFramework\Unit\Autoloader\ExtensionAttributesGenerator; class ExtensionAttributesGeneratorTest extends \PHPUnit\Framework\TestCase { private $subject; protected function setUp() { $this->subject = new ExtensionAttributesGenerator(); } public function testGenerateExtensionAttributes() { $this->assertStringMatchesFormat( "%Anamespace My;%Aclass SimpleExtension implements SimpleExtensionInterface%A", $this->subject->generate('\My\SimpleExtension') ); } public function testGenerateNonExtensionAttributes($className) { $this->assertFalse($this->subject->generate($className)); } public function generateNonExtensionAttributesDataProvider() { return [ 'non-extension attribute class' => ['\My\SimpleClass'], 'non-conventional extension attribute name' => ['\My\Extension'], ]; } } 